import{_ as i,o as a,c as n,a4 as t}from"./chunks/framework.B-wJupoK.js";const e="/assets/image-20250118233735515.IwkKQFCY.png",l="/assets/image-20250118235504943.CenHE6Ku.png",h="/assets/image-20250119000030512.DZ51owJN.png",p="/assets/image-20250119001021913.CJJSVvxh.png",k="/assets/image-20250119021913620.CHbtvNse.png",r="/assets/image-20250119022910282.C5R0cXit.png",d="/assets/image-20250119023215094.D4ZjAoie.png",m=JSON.parse('{"title":"HarmonyOSNext 端云一体化（5）","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/HarmonyOSNext 端云一体化/HarmonyOSNext 端云一体化（5）/HarmonyOSNext 端云一体化（5）.md","filePath":"鸿蒙开发技巧/HarmonyOSNext 端云一体化/HarmonyOSNext 端云一体化（5）/HarmonyOSNext 端云一体化（5）.md","lastUpdated":1773020038000,"__rawMarkdown":"# HarmonyOSNext 端云一体化（5）\\n\\n上一章节我们主要讲解了查询条件-谓词的基本使用技巧。这一章我们主要来讲解下**客户端操作云存储。**\\n\\n## 云存储介绍\\n\\n云储存就是提供了一个可以存储物理文件的云端环境，比如存储图片、视频、音乐等，同时提供了的客户端操作云存储、云函数操作云存储的能力。我们这里主要讲解**客户端操作存储**，后续会讲解云函数操作云存储。\\n\\n## 云存储的计费策略\\n\\n### 免费配额\\n\\n开通云存储服务后，华为供了免费额度以供试用，具体的配额明细如下。\\n\\n| 计费项               | 详细说明                                                     | 免费配额                                                     |\\n| :------------------- | :----------------------------------------------------------- | :----------------------------------------------------------- |\\n| 存储                 | 存储数据的容量，以小时为统计周期，UTC时间整点结算，单位为GB。 | 5GB注意“存储”为按月计费，而非一次性计费。如果您使用的存储容量每月都超过免费配额，您每月都需支付相应的超额费用。例如，本月您使用了6GB存储容量，则本月您需支付1GB的超额费用。如果下个月您服务的存储容量为7GB，下个月您仍需支付2GB的超额费用。 |\\n| 网络出站流量         | 公网流出流量，即通过互联网从云存储下载数据产生的流量。       | 1GB/天                                                       |\\n| 上传操作次数         | 上传接口请求次数。                                           | 20,000/天                                                    |\\n| 下载操作次数         | 下载接口请求次数。                                           | 50,000/天                                                    |\\n| 每个项目多个存储实例 | 单个项目支持创建多个存储实例。                               | **免费档不支持此功能**                                       |\\n\\n> 以某工具类APP为例，月新增下载量近1w，云存储提供的免费配额完全能支撑APP日常的调用。\\n\\n### 升级到按量付费档\\n\\n当统计周期内的免费配额即将用尽时，您可以选择升级到按量付费档，以继续使用服务。或者，您也可以等到下个统计周期再使用云存储服务，在此之前服务将不再可用。\\n\\n云存储按量付费价格如下表所示，套餐升级操作请参见[升级到付费档](https://developer.huawei.com/consumer/cn/doc/development/AppGallery-connect-Guides/agc-service-billing-0000001058092595#section1337763420106)。\\n\\n| 计费项               | 详细说明                                                     | 按量付费价格         |\\n| :------------------- | :----------------------------------------------------------- | :------------------- |\\n| 存储                 | 存储数据的容量，以小时为统计周期，UTC时间整点结算，单位为GB。 | CNY 0.1679/GB        |\\n| 网络出站流量         | 公网流出流量，即通过互联网从云存储下载数据产生的流量。       | CNY 0.7751/GB        |\\n| 上传操作次数         | 上传接口请求次数。                                           | CNY 0.323/10,000     |\\n| 下载操作次数         | 下载接口请求次数。                                           | CNY 0.0258/10,000    |\\n| 每个项目多个存储实例 | 单个项目支持创建多个存储实例。                               | 按量付费档支持此功能 |\\n\\n\\n\\n## 云存储核心功能\\n\\n客户端操作存储的核心功能主要有以下。\\n\\n- 上传文件到云端\\n- 查看云端文件列表\\n- 查看云端文件元数据\\n- 设置云端文件数据\\n- 获取云端文件下载地址\\n- 下载云端文件到本地\\n- 删除云端文件\\n\\n接下来我们便开始对云存储进行操作。\\n\\n## 准备环境\\n\\n### 开通云存储\\n\\n我们需要提前在AGC平台上开通云存储环境。\\n\\n![image-20250118233735515](assets/image-20250118233735515.png)\\n\\n我们可以看到，这个的云存储的实例名称为 **default-bucket-xxxx**\\n\\n### 初始化云存储实例\\n\\n因为后期要操作云存储都需要用到云存储实例。所以需要初始化好。\\n\\n### 使用默认云存储实例\\n\\n```typescript\\n bucket: cloudStorage.StorageBucket = cloudStorage.bucket(); // 获取默认的存储实例\\n```\\n\\n### 指定云存储实例\\n\\n```typescript\\n bucket: cloudStorage.StorageBucket = cloudStorage.bucket(\\"default-bucket-xxxx\\"); // 获取默认的存储实例\\n```\\n\\n##  上传文件到云端\\n\\n上传文件到云端只能调用[StorageBucket.uploadFile](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section2105131521913)方法，但是该方法要求上传的文件路径必须存放在**context.cacheDir**目录下。因\\n\\n此需要先提前做好这个处理。\\n\\n**步骤：**\\n\\n1. 选择待上传的文件，下方示例代码中使用[photoAccessHelper.PhotoViewPicker](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-photoaccesshelper-V5#photoviewpicker)指定需要上传的文件。\\n2. 将待上传的文件复制到context.cacheDir目录下。\\n3. 调用[StorageBucket.uploadFile](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section2105131521913)接口创建上传任务，监听上传任务的progress、completed、failed等事件。\\n4. 启动上传任务。\\n\\n\\n\\n> uploadFile在上传文件时，还支持上传自定义的标准的http头部信息。具体可以查看API说明\\n\\n**示例代码：**\\n\\n```jsx\\nfn8 = async () => {\\n    // 使用photoAccessHelper选择指定的文件\\n    let photoSelectOptions = new photoAccessHelper.PhotoSelectOptions();\\n    // 设置媒体文件类型为图像\\n    photoSelectOptions.MIMEType = photoAccessHelper.PhotoViewMIMETypes.IMAGE_TYPE; \\n    // 设置选择媒体文件的最大数目为1\\n    photoSelectOptions.maxSelectNumber = 1; \\n    let photoViewPicker = new photoAccessHelper.PhotoViewPicker();\\n    // 调用select方法选择图片，并处理选择结果\\n    photoViewPicker.select(photoSelectOptions).then((photoSelectResult: photoAccessHelper.PhotoSelectResult) => {\\n      // 获取选中文件的URI\\n      let fileUri = photoSelectResult.photoUris[0];\\n      console.info(`pick file ${fileUri}`);\\n      // 提取文件名\\n      let fileName = fileUri.split(\'/\').pop() as string;\\n      console.info(`file name ${fileName}`);\\n      // 创建缓存文件名，以当前时间戳和原文件名组合\\n      let cacheFile = `${Date.now()}_${fileName}`;\\n      console.info(`cacheFile ${cacheFile}`);\\n      // 拼接缓存文件路径\\n      let cacheFilePath = getContext().cacheDir + \'/\' + cacheFile;\\n\\n      // 将选中文件复制到缓存目录下，文件名为cacheFile\\n      try {\\n        // 打开源文件\\n        let srcFile = fs.openSync(fileUri);\\n        // 打开目标文件（创建或读写）\\n        let dstFile = fs.openSync(cacheFilePath, fs.OpenMode.READ_WRITE | fs.OpenMode.CREATE);\\n        // 复制文件内容\\n        fs.copyFileSync(srcFile.fd, dstFile.fd);\\n        // 关闭源文件\\n        fs.closeSync(srcFile);\\n        // 关闭目标文件\\n        fs.closeSync(dstFile);\\n      } catch (e) {\\n        console.info(`copy file failed ${e.message}`);\\n        return;\\n      }\\n\\n      // 使用默认实例上传文件至云存储\\n      this.bucket.uploadFile(getContext(this), {\\n        // 本地文件路径，位于context.cacheDir目录下\\n        localPath: cacheFile, \\n        // 云端存储路径\\n        cloudPath: fileName    \\n      }).then((task: request.agent.Task) => {\\n        // 监听任务进度\\n        task.on(\'progress\', (progress) => {\\n          console.info(`on progress ${JSON.stringify(progress)}`);\\n        });\\n        // 监听任务完成\\n        task.on(\'completed\', (progress) => {\\n          console.info(`on completed ${JSON.stringify(progress)}`);\\n        });\\n        // 监听任务失败\\n        task.on(\'failed\', (progress) => {\\n          console.error(`on failed ${JSON.stringify(progress)}`);\\n        });\\n        // 监听任务响应\\n        task.on(\'response\', (response) => {\\n          console.info(`on response ${JSON.stringify(response)}`);\\n        });\\n\\n        // 启动任务，并处理启动结果\\n        task.start((err: BusinessError) => {\\n          if (err) {\\n            console.error(`Failed to start the uploadFile task, Code: ${err.code}, message: ${err.message}`);\\n          } else {\\n            console.info(`Succeeded in starting a uploadFile task.`);\\n          }\\n        });\\n      }).catch((err: BusinessError) => {\\n        console.error(`uploadFile failed, Code: ${err.code}, message: ${err.message}`);\\n      });\\n    })\\n}\\n\\n      Button(\\"计算8 上传文件到云端\\")\\n        .onClick(this.fn8)\\n\\n```\\n\\n**刷新AGC-中的云存储：**  可以看到文件成功上传了。\\n\\n![image-20250118235504943](assets/image-20250118235504943.png)\\n\\n\\n\\n##  查看云端文件列表\\n\\n如果想要获取云端文件列表，可以使用 **StorageBucket.list** API。\\n\\n### 参数\\n\\n| 参数名    | 类型                                                         | 必填 | 说明                 |\\n| :-------- | :----------------------------------------------------------- | :--- | :------------------- |\\n| cloudPath | string                                                       | 是   | 云侧文件路径。       |\\n| options   | [ListOptions](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section7984102813013) | 否   | 列举操作的相关参数。 |\\n\\n**ListOptions**\\n\\n| 名称       | 类型   | 只读 | 可选 | 说明                                                     |\\n| :--------- | :----- | :--- | :--- | :------------------------------------------------------- |\\n| maxResults | number | 否   | 是   | 列举文件的最大数量，取值范围1-1000，默认则列举所有文件。 |\\n| pageMarker | string | 否   | 是   | 分页标识。                                               |\\n\\n### 返回内容\\n\\n| 名称        | 类型     | 只读 | 可选 | 说明                         |\\n| :---------- | :------- | :--- | :--- | :--------------------------- |\\n| directories | string[] | 否   | 否   | 列举操作返回的云侧目录列表。 |\\n| files       | string[] | 否   | 否   | 列举操作返回的云侧文件列表。 |\\n| pageMarker  | string   | 否   | 是   | 分页标识。                   |\\n\\n### **示例代码**\\n\\n```typescript\\n  fn9 = async () => {\\n    try {\\n      const res = await this.bucket.list(\'\') // 获取根据根路径\\n      // const res = await this.bucket.list(\'avatar/\') // 获取 avatar/ 路径下的文件。 需要注意的是 如果你输入的路径是 ava ,那么 avatar也会被匹配到\\n      AlertDialog.show({ message: JSON.stringify(res, null, 2) })\\n    } catch (e) {\\n      promptAction.showToast({ message: `${e.message} ${e.code}` })\\n    }\\n  }\\n  \\n    Button(\\"计算9 获取云端文件列表\\")\\n    .onClick(this.fn9)\\n```\\n\\n### **得到结果**\\n\\n![image-20250119000030512](assets/image-20250119000030512.png)\\n\\n\\n\\n##  查看云端文件元数据\\n\\n我们可以通过该[StorageBucket.getMetadata](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section2031534817364)API获取到文件名、文件大小、文件类型等常用属性，也包括用户自定义的文件属性。\\n\\n### 参数\\n\\n| 参数名    | 类型   | 必填 | 说明           |\\n| :-------- | :----- | :--- | :------------- |\\n| cloudPath | string | 是   | 云侧文件路径。 |\\n\\n### 返回值\\n\\n| 类型                                                         | 说明                                    |\\n| :----------------------------------------------------------- | :-------------------------------------- |\\n| Promise<[Metadata](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section3472335144212)> | Promise对象，返回云侧文件的元数据信息。 |\\n\\n### 示例代码\\n\\n```typescript\\n  fn10 = async () => {\\n    try {\\n      const res = await this.bucket.list(\'\')\\n      const cloudFilePath = res.files[0] // 获取第一个文件 -  实际开发中，你需要明确该路径下一定存在文件\\n      const res2 = await this.bucket.getMetadata(cloudFilePath)\\n      AlertDialog.show({ message: JSON.stringify(res2, null, 2) })\\n    } catch (e) {\\n      promptAction.showToast({ message: `${e.message} ${e.code}` })\\n    }\\n  }\\n  \\nButton(\\"计算10 查看云端文件元数据\\")\\n.onClick(this.fn10)\\n```\\n\\n\\n\\n### 得到结果\\n\\n![image-20250119001021913](assets/image-20250119001021913.png)\\n\\n\\n\\n\\n\\n##  获取云端文件下载地址\\n\\n我们之前通过`getMetadata`获取到了云端文件的相关信息。但是如果该文件是图片，而我们想要使用Image显示该图片，那么还需要使用[StorageBucket.getDownloadURL](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section9969145143317)获取到该文件的下载地址。\\n\\n### 参数\\n\\n| 参数名    | 类型   | 必填 | 说明           |\\n| :-------- | :----- | :--- | :------------- |\\n| cloudPath | string | 是   | 云侧文件路径。 |\\n\\n### 返回值\\n\\n| `类型`            | `说明`                              |\\n| :---------------- | :---------------------------------- |\\n| `Promise<string>` | Promise对象，返回云侧文件下载地址。 |\\n\\n### 示例代码\\n\\n```jsx\\n  fn11 = async () => {\\n    try {\\n      const res = await this.bucket.list(\'\')\\n      const cloudFilePath = res.files[0] // 获取第一个文件 -  实际开发中，你需要明确该路径下一定存在文件\\n      const res2 = await this.bucket.getDownloadURL(cloudFilePath)\\n      AlertDialog.show({ message: JSON.stringify(res2, null, 2) })\\n    } catch (e) {\\n      promptAction.showToast({ message: `${e.message} ${e.code}` })\\n    }\\n  }\\n  \\nButton(\\"计算11 获取云端文件下载地址\\")\\n.onClick(this.fn11)\\n```\\n\\n### 得到结果\\n\\n![image-20250119021913620](assets/image-20250119021913620.png)\\n\\n##  下载云端文件到本地\\n\\n利用 [StorageBucket.downloadFile](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section02263293319)  可以将文件下载到 `ontext.cacheDir` 目录下。\\n\\n### 参数\\n\\n| 参数名     | 类型                                                         | 必填 | 说明           |\\n| :--------- | :----------------------------------------------------------- | :--- | :------------- |\\n| context    | common.[BaseContext](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-inner-application-basecontext-V5) | 是   | 应用上下文。   |\\n| parameters | [DownloadParams](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section14137913019) | 是   | 下载相关参数。 |\\n\\n**DownloadParams**\\n\\n| 名称      | 类型                                                         | 只读 | 可选 | 说明                                                         |\\n| :-------- | :----------------------------------------------------------- | :--- | :--- | :----------------------------------------------------------- |\\n| localPath | string                                                       | 否   | 否   | 本地文件路径，根路径为cache目录。                            |\\n| cloudPath | string                                                       | 否   | 否   | 云侧文件路径。                                               |\\n| mode      | [request.agent.Mode](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-request-V5#mode10) | 否   | 是   | 下载任务类型，前端任务在应用切换到后台一段时间后失败/暂停；后台任务不受影响。默认为BACKGROUND。BACKGROUND：后台任务。FOREGROUND：前端任务。 |\\n| overwrite | boolean                                                      | 否   | 是   | 当本地文件已存在时，是否覆盖本地文件，默认false。true：覆盖本地文件。false：不覆盖，若存在同名文件则下载失败。 |\\n| network   | [request.agent.Network](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/js-apis-request-V5#network10) | 否   | 是   | 下载任务的网络配置，网络不满足设置条件时，未执行的任务等待执行，执行中的任务失败/暂停。默认为ANY。ANY：不限网络类型。WIFI：无线网络。CELLULAR：蜂窝数据网络。 |\\n\\n### 返回值\\n\\n| 类型              | 说明                        |\\n| :---------------- | :-------------------------- |\\n| `Promise<[Task]>` | Promise对象，返回下载任务。 |\\n\\n### 示例代码\\n\\n```jsx\\n  fn12 = async () => {\\n    try {\\n      const res = await this.bucket.list(\'\')\\n      const cloudFilePath = res.files[0] // 获取第一个文件 -  实际开发中，你需要明确该路径下一定存在文件\\n      const task = await this.bucket.downloadFile(getContext(this), {\\n        localPath: Date.now().toString(), // 本地文件路径, 下载成功后，文件将会保存在context.cacheDir目录\\n        cloudPath: cloudFilePath  // 云侧文件路径\\n      })\\n      task.on(\'progress\', (progress) => {\\n        console.info(`on progress ${JSON.stringify(progress)} `);\\n      });\\n      task.on(\'completed\', (progress) => {\\n        console.info(`on completed ${JSON.stringify(progress)} `);\\n        AlertDialog.show({ message: JSON.stringify(\\"下载完成\\", null, 2) })\\n      });\\n      task.on(\'failed\', (progress) => {\\n        console.error(`on failed ${JSON.stringify(progress)} `);\\n      });\\n      task.on(\'response\', (response) => {\\n        console.info(`on response ${JSON.stringify(response)} `);\\n      });\\n      task.start((err: BusinessError) => {\\n        if (err) {\\n          console.error(`Failed to start the downloadFile task, Code: ${err.code}, message: ${err.message}`);\\n        } else {\\n          console.info(`Succeeded in starting a downloadFile task. result: ${task.tid}`);\\n        }\\n      });\\n    } catch (e) {\\n      promptAction.showToast({ message: `${e.message} ${e.code}` })\\n    }\\n  }\\n\\n\\n  Button(\\"计算12 下载云端文件\\")\\n    .onClick(this.fn12)\\n```\\n\\n\\n\\n### 得到结果\\n\\n![image-20250119022910282](assets/image-20250119022910282.png)\\n\\n##  删除云端文件\\n\\n调用[StorageBucket.deleteFile](https://developer.huawei.com/consumer/cn/doc/harmonyos-references-V5/cloudfoundation-cloudstorage-V5#section1290422653419)删除云侧的文件。\\n\\n### 参数\\n\\n| 参数名    | 类型   | 必填 | 说明           |\\n| :-------- | :----- | :--- | :------------- |\\n| cloudPath | string | 是   | 云侧文件路径。 |\\n\\n### 返回值\\n\\n| 类型            | 说明                                   |\\n| :-------------- | :------------------------------------- |\\n| `Promise<void>` | Promise对象。无返回结果的Promise对象。 |\\n\\n### 示例代码\\n\\n```\\n  fn13 = async () => {\\n    try {\\n      const res = await this.bucket.list(\'\')\\n      const cloudFilePath = res.files[0] // 获取第一个文件 -  实际开发中，你需要明确该路径下一定存在文件\\n      await this.bucket.deleteFile(cloudFilePath)\\n      promptAction.showToast({ message: `${\\"成功\\"}` })\\n    } catch (e) {\\n      promptAction.showToast({ message: `${e.message} ${e.code}` })\\n    }\\n  }\\n```\\n\\n\\n\\n### 得到结果\\n\\n![image-20250119023215094](assets/image-20250119023215094.png)\\n\\n\\n\\n\\n\\n## 总结\\n\\n本文详细介绍了HarmonyOS Next中云存储的基本使用方法。主要内容包括：\\n\\n1. **云存储基础**\\n   - 介绍了云存储的基本概念\\n   - 详细说明了免费配额和计费策略\\n   - 讲解了云存储的核心功能\\n\\n2. **环境准备**\\n   - 如何在AGC平台开通云存储\\n   - 如何初始化云存储实例，包括默认实例和指定实例的使用\\n\\n3. **核心API使用**\\n   - 文件上传：使用`uploadFile`将本地文件上传至云端\\n   - 文件列表：通过`list`获取云端文件列表\\n   - 元数据获取：使用`getMetadata`查看文件的详细信息\\n   - 下载地址：通过`getDownloadURL`获取文件的下载链接\\n   - 文件下载：使用`downloadFile`将云端文件下载到本地\\n   - 文件删除：通过`deleteFile`删除云端文件\\n\\n4. **注意事项**\\n   - 文件上传必须使用`context.cacheDir`目录\\n   - 文件下载同样只能保存在`context.cacheDir`目录下\\n   - 操作云存储时需要注意错误处理\\n\\n通过本文的学习，开发者可以掌握HarmonyOS Next中云存储的基本操作，为应用开发中的文件存储需求提供解决方案。\\n\\n\\n\\n\\n\\n---\\n\\n如果你兴趣想要了解更多的鸿蒙应用开发细节和最新资讯，欢迎在评论区留言或者私信或者看我个人信息，可以加入技术交流群。\\n\\n\\n\\n"}'),E={name:"鸿蒙开发技巧/HarmonyOSNext 端云一体化/HarmonyOSNext 端云一体化（5）/HarmonyOSNext 端云一体化（5）.md"};function o(g,s,c,y,F,u){return a(),n("div",null,[...s[0]||(s[0]=[t("",98)])])}const f=i(E,[["render",o]]);export{m as __pageData,f as default};
